    # line seed. Extend its diagonal through background cells to both borders,
    # stopping at any existing foreground cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
