                    continue
                if grid[r][c + dc] != bg or grid[r + dr][c] != bg:
                    continue
                # Walk the complete diagonal, preserving the two seed cells;
                # each outward branch stops at the first non-background cell.
                x, y = r - dr, c - dc
                while 0 <= x < h and 0 <= y < w and grid[x][y] == bg:
                    out[x][y] = color
                    x -= dr
                    y -= dc
                x, y = rr + dr, cc + dc
                while 0 <= x < h and 0 <= y < w and grid[x][y] == bg:
                    out[x][y] = color
