        rect_cells[color] = set()
        for r in range(h):
            for c in range(w):
                if seen[r][c] or grid[r][c] != color:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
